-- 3.15.1 Israel furniture-core price evidence v1.
-- Current Home Center listings retrieved 2026-09-28. All offers remain
-- candidates and VAT is left unknown because the captured listings do not
-- state whether displayed prices include VAT.

on conflict(source_id) do update set source_type=excluded.source_type,source_channel=excluded.source_channel,source_name=excluded.source_name,source_url=excluded.source_url,source_date=excluded.source_date,language_code=excluded.language_code,region=excluded.region,evidence=excluded.evidence,retrieved_at=now();

on conflict(material_code) do update set department=excluded.department,category_code=excluded.category_code,canonical_name=excluded.canonical_name,base_unit=excluded.base_unit,specifications=excluded.specifications,active=true,updated_at=now();

select material_id,'IL',case material_code
when 'drawer_runner_basic_pair_300mm' then 'מסילה בסיסית למגירה 30 ס״מ, זוג'
when 'drawer_runner_basic_pair_350mm' then 'מסילה בסיסית למגירה 35 ס״מ, זוג'
when 'drawer_runner_basic_pair_400mm' then 'מסילה בסיסית למגירה 40 ס״מ, זוג'
when 'drawer_runner_basic_pair_450mm' then 'מסילה בסיסית למגירה 45 ס״מ, זוג'
when 'drawer_runner_basic_pair_500mm' then 'מסילה בסיסית למגירה 50 ס״מ, זוג'
when 'drawer_runner_basic_pair_550mm' then 'מסילה בסיסית למגירה 55 ס״מ, זוג'
when 'shelf_support_plastic_brown_nail' then 'תומך מדף מפלסטיק חום עם מסמר'
when 'shelf_support_plastic_white_nail' then 'תומך מדף מפלסטיק לבן עם מסמר'
when 'shelf_support_plastic_brown_metal_pin' then 'תומך מדף מפלסטיק חום עם פין מתכת'
when 'shelf_support_plastic_white_metal_pin' then 'תומך מדף מפלסטיק לבן עם פין מתכת'
when 'shelf_support_duplo_metal_5x7_5mm' then 'תומך מדף דופלו מתכת 5×7.5 מ״מ'
when 'shelf_support_plastic_clear_metal_pin' then 'תומך מדף מפלסטיק שקוף עם פין מתכת'
when 'glide_eva_nail_26mm_white_pack8' then 'רגל מסמר EVA לבנה 26 מ״מ'
when 'glide_ptfe_screw_50mm_pack4' then 'מחליק טפלון עגול עם בורג 50 מ״מ'
when 'bumper_rubber_round_22mm_black_pack16' then 'מדבקת גומי עגולה שחורה 22 מ״מ'
when 'glide_nylon_nail_26mm_white_pack8' then 'רגל מסמר ניילון לבנה 26 מ״מ'
when 'bumper_silicone_25mm_pack12' then 'בועת סיליקון לרהיטים 25 מ״מ'
when 'foot_rubber_22mm_white_pack4' then 'רגלית גומי לבנה 22 מ״מ'
when 'glide_ptfe_round_20mm_pack8' then 'מחליק טפלון עגול 20 מ״מ'
when 'glide_ptfe_square_50mm_pack4' then 'מחליק טפלון מרובע 50×50 מ״מ'
when 'glide_ptfe_rectangle_100x25mm_pack4' then 'מחליק טפלון מלבני 100×25 מ״מ'
when 'pad_felt_round_22mm_black_pack16' then 'רפידת לבד עגולה שחורה 22 מ״מ'
end,'he-IL','{"market":"Israel","source_language":"Hebrew"}'::jsonb,'common'
from public.reference_materials where material_code in (
'drawer_runner_basic_pair_300mm','drawer_runner_basic_pair_350mm','drawer_runner_basic_pair_400mm','drawer_runner_basic_pair_450mm','drawer_runner_basic_pair_500mm','drawer_runner_basic_pair_550mm',
'shelf_support_plastic_brown_nail','shelf_support_plastic_white_nail','shelf_support_plastic_brown_metal_pin','shelf_support_plastic_white_metal_pin','shelf_support_duplo_metal_5x7_5mm','shelf_support_plastic_clear_metal_pin',
'glide_eva_nail_26mm_white_pack8','glide_ptfe_screw_50mm_pack4','bumper_rubber_round_22mm_black_pack16','glide_nylon_nail_26mm_white_pack8','bumper_silicone_25mm_pack12','foot_rubber_22mm_white_pack4','glide_ptfe_round_20mm_pack8','glide_ptfe_square_50mm_pack4','glide_ptfe_rectangle_100x25mm_pack4','pad_felt_round_22mm_black_pack16')
on conflict(material_id,market_code,language_code) do update set market_name=excluded.market_name,local_specifications=excluded.local_specifications,availability_status=excluded.availability_status,active=true,updated_at=now();

on conflict(market_offer_id) do update set source_price=excluded.source_price,source_currency=excluded.source_currency,source_unit=excluded.source_unit,price_scope=excluded.price_scope,included_services=excluded.included_services,delivery_included=excluded.delivery_included,package_quantity=excluded.package_quantity,minimum_order_quantity=excluded.minimum_order_quantity,vat_mode=excluded.vat_mode,normalized_price_ex_vat=excluded.normalized_price_ex_vat,normalized_unit=excluded.normalized_unit,conversion_basis=excluded.conversion_basis,region=excluded.region,valid_from=excluded.valid_from,confidence=excluded.confidence,status=excluded.status;
